#!/usr/bin/env node
'use strict';
// AI: below section was generated by an AI
/*
 * Browser smoke test for the /home page against the mock (or a real device):
 * loads the page at 390x844, records console errors, page errors and failed requests, clicks every tab
 * in the bottom navigation and prints a summary.
 *
 *   node smoke.js [--url http://127.0.0.1:8080/home] [--start] [--shots <dir>] [--dark] [--wait ms]
 *
 * --start launches server.js on a free port first (extra arguments after "--" are passed to it).
 * Uses an already installed Playwright (or Puppeteer); nothing is installed. Set PLAYWRIGHT_PATH or
 * PUPPETEER_PATH to point at a package directory if it is not found automatically.
 */
const { execSync, spawn } = require('child_process');
const fs = require('fs');
const net = require('net');
const path = require('path');

const argv = process.argv.slice(2);
const dd = argv.indexOf('--');
const serverArgs = dd >= 0 ? argv.slice(dd + 1) : [];
const args = dd >= 0 ? argv.slice(0, dd) : argv;
const opt = { url: null, start: false, shots: null, dark: false, wait: 1500 };
for (let i = 0; i < args.length; i++) {
  if (args[i] === '--url') opt.url = args[++i];
  else if (args[i] === '--start') opt.start = true;
  else if (args[i] === '--shots') opt.shots = path.resolve(args[++i]);
  else if (args[i] === '--dark') opt.dark = true;
  else if (args[i] === '--wait') opt.wait = +args[++i];
}
if (!opt.url && !opt.start) opt.start = true;

// find an installed browser automation library without installing anything
function findLib() {
  const tryReq = (p) => { try { return require(p); } catch (_) { return null; } };
  const cands = [];
  if (process.env.PLAYWRIGHT_PATH) cands.push(['playwright', process.env.PLAYWRIGHT_PATH]);
  if (process.env.PUPPETEER_PATH) cands.push(['puppeteer', process.env.PUPPETEER_PATH]);
  cands.push(['playwright', 'playwright'], ['puppeteer', 'puppeteer']);
  const roots = [path.resolve(__dirname, '..', '..', 'WLED-main', 'node_modules')];
  try { roots.push(execSync('npm root -g', { stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim()); } catch (_) {}
  for (const root of roots) {
    if (!fs.existsSync(root)) continue;
    for (const name of ['playwright', 'puppeteer']) cands.push([name, path.join(root, name)]);
    for (const pkg of fs.readdirSync(root)) {  // packages that bring their own copy (one level deep)
      for (const name of ['playwright', 'puppeteer']) cands.push([name, path.join(root, pkg, 'node_modules', name)]);
    }
  }
  for (const [kind, p] of cands) {
    if (p.includes(path.sep) && !fs.existsSync(p)) continue;
    const lib = tryReq(p);
    if (lib && (kind === 'playwright' ? lib.chromium : lib.launch)) return { kind, lib, where: p };
  }
  return null;
}

const freePort = () => new Promise((res) => { const s = net.createServer(); s.listen(0, '127.0.0.1', () => { const p = s.address().port; s.close(() => res(p)); }); });
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function main() {
  const found = findLib();
  if (!found) {
    console.log('smoke: neither playwright nor puppeteer is installed anywhere reachable (checked require paths, WLED-main/node_modules, global npm root).');
    console.log('       Set PLAYWRIGHT_PATH / PUPPETEER_PATH to an existing package directory to use one.');
    process.exit(3);
  }
  console.log('using ' + found.kind + ' from ' + found.where);

  let child = null;
  if (opt.start) {
    const port = await freePort();
    child = spawn(process.execPath, [path.join(__dirname, 'server.js'), '--port', String(port), ...serverArgs], { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    child.stdout.on('data', d => { out += d; });
    child.stderr.on('data', d => { out += d; });
    for (let i = 0; i < 100 && !/mock on http/.test(out); i++) { if (child.exitCode !== null) break; await sleep(50); }
    if (!/mock on http/.test(out)) { console.log(out); process.exit(2); }
    opt.url = 'http://127.0.0.1:' + port + '/home';
    console.log('mock started: ' + opt.url);
  }

  const consoleErrors = [], pageErrors = [], failed = [], tabs = [];
  let browser, page;
  const vp = { width: 390, height: 844 };
  if (found.kind === 'playwright') {
    const tries = [{}, { channel: 'chrome' }, { channel: 'msedge' }];
    for (const t of tries) { try { browser = await found.lib.chromium.launch(Object.assign({ headless: true }, t)); break; } catch (e) { if (t === tries[tries.length - 1]) throw e; } }
    const ctx = await browser.newContext({ viewport: vp, deviceScaleFactor: 2, isMobile: true, hasTouch: true, colorScheme: opt.dark ? 'dark' : 'light' });
    page = await ctx.newPage();
  } else {
    browser = await found.lib.launch({ headless: 'new' });
    page = await browser.newPage();
    await page.setViewport(Object.assign({ deviceScaleFactor: 2, isMobile: true, hasTouch: true }, vp));
    if (opt.dark) await page.emulateMediaFeatures([{ name: 'prefers-color-scheme', value: 'dark' }]);
  }
  page.on('console', m => { if (m.type() === 'error') consoleErrors.push(m.text()); });
  page.on('pageerror', e => pageErrors.push(String(e && e.message || e)));
  page.on('response', r => { if (r.status() >= 400) failed.push(r.status() + ' ' + r.request().method() + ' ' + r.url().replace(/^https?:\/\/[^/]+/, '')); });
  page.on('requestfailed', r => failed.push('ERR ' + r.method() + ' ' + r.url().replace(/^https?:\/\/[^/]+/, '')));
  if (opt.shots) fs.mkdirSync(opt.shots, { recursive: true });

  await page.goto(opt.url, { waitUntil: 'load' });
  await sleep(opt.wait);
  const title = await page.title();
  const navCount = await page.evaluate(() => (document.querySelector('#nav') ? document.querySelector('#nav').children.length : 0));
  for (let i = 0; i < navCount; i++) {
    const errsBefore = pageErrors.length + consoleErrors.length;
    await page.evaluate((k) => document.querySelector('#nav').children[k].click(), i);
    await sleep(opt.wait);
    const info = await page.evaluate(() => {
      const main = [...document.querySelectorAll('main > section, main > div, [id^="t-"]')].find(e => !e.hidden && e.offsetParent !== null) || document.body;
      const label = document.querySelector('#nav .sel') ? document.querySelector('#nav .sel').textContent.trim() : location.hash;
      return { label, hash: location.hash, textLen: (main.innerText || '').trim().length, hscroll: document.documentElement.scrollWidth > window.innerWidth + 1, buttons: main.querySelectorAll('button').length };
    });
    info.newErrors = pageErrors.length + consoleErrors.length - errsBefore;
    tabs.push(info);
    if (opt.shots) await page.screenshot({ path: path.join(opt.shots, 'tab' + i + '-' + (info.hash.slice(1) || i) + '.png'), fullPage: true });
  }
  await browser.close();
  if (child) child.kill();

  console.log('\npage "' + title + '" at 390x844' + (opt.dark ? ' (dark)' : ''));
  console.log('tabs:');
  for (const t of tabs) console.log('  ' + (t.label || '?').padEnd(18) + ' ' + t.hash.padEnd(10) + ' text ' + String(t.textLen).padStart(5) + ' chars, ' + String(t.buttons).padStart(3) + ' buttons' + (t.hscroll ? ', HORIZONTAL SCROLL' : '') + (t.newErrors ? ', ' + t.newErrors + ' new error(s)' : ''));
  const uniq = a => [...new Set(a)];
  console.log('page errors (' + pageErrors.length + '):'); uniq(pageErrors).forEach(e => console.log('  ' + e));
  console.log('console errors (' + consoleErrors.length + '):'); uniq(consoleErrors).forEach(e => console.log('  ' + e));
  console.log('failed requests (' + failed.length + '):'); uniq(failed).forEach(e => console.log('  ' + e + '  x' + failed.filter(x => x === e).length));
  const bad = pageErrors.length + tabs.filter(t => t.hscroll || !t.textLen).length;
  console.log('\n' + (bad ? 'SMOKE: ' + bad + ' problem(s)' : 'SMOKE: ok') + ' - ' + tabs.length + ' tabs, ' + pageErrors.length + ' page errors, ' + consoleErrors.length + ' console errors, ' + failed.length + ' failed requests');
  process.exit(bad ? 1 : 0);
}

main().catch(e => { console.error(e); process.exit(2); });
// AI: end
